CREATE TABLE IF NOT EXISTS pacientes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(120) NOT NULL, cpf VARCHAR(11) NOT NULL UNIQUE, nascimento VARCHAR(10) NOT NULL, telefone VARCHAR(30), email VARCHAR(120), alergias VARCHAR(255));
CREATE TABLE IF NOT EXISTS medicos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(120) NOT NULL, crm VARCHAR(40) NOT NULL UNIQUE, especialidade VARCHAR(100) NOT NULL, email VARCHAR(120));
CREATE TABLE IF NOT EXISTS consultas (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, paciente BIGINT NOT NULL REFERENCES pacientes(id), medico BIGINT NOT NULL REFERENCES medicos(id), data VARCHAR(10) NOT NULL, hora VARCHAR(5) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'Agendada');
CREATE TABLE IF NOT EXISTS convenios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, paciente BIGINT NOT NULL REFERENCES pacientes(id), nome VARCHAR(120) NOT NULL, tipo VARCHAR(120) NOT NULL, contato VARCHAR(120));
CREATE TABLE IF NOT EXISTS prontuarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, paciente BIGINT NOT NULL REFERENCES pacientes(id), diagnostico VARCHAR(255) NOT NULL, descricao VARCHAR(2000) NOT NULL);
